import{_ as t,c as a,o as n,a0 as s}from"./chunks/framework.oTSD2LDJ.js";const k=JSON.parse('{"title":"CppExt 后端概览","description":"","frontmatter":{"title":"CppExt 后端概览","editLink":true},"headers":[],"relativePath":"controls-reference/cpp-ext/overview.md","filePath":"zh/controls-reference/cpp-ext/overview.md"}'),i={name:"controls-reference/cpp-ext/overview.md"};function o(d,e,r,l,p,c){return n(),a("div",null,e[0]||(e[0]=[s(`<h1 id="cppext-后端模块总览" tabindex="-1">CppExt 后端模块总览 <a class="header-anchor" href="#cppext-后端模块总览" aria-label="Permalink to &quot;CppExt 后端模块总览&quot;">​</a></h1><p><code>CppExt</code> 文件夹包含了 UniDesk 框架的 C++ 后端实现，为 QML 控件提供底层能力支撑。这些 C++ 类通过 <code>Q_PROPERTY</code>、<code>Q_INVOKABLE</code> 和信号等机制暴露给 QML 使用，涵盖了全局状态、设置持久化、插件管理、模板系统、系统信息采集、表达式引擎等核心功能。</p><h2 id="模块列表" tabindex="-1">模块列表 <a class="header-anchor" href="#模块列表" aria-label="Permalink to &quot;模块列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类名</th><th>功能</th><th>关联 QML 单例</th></tr></thead><tbody><tr><td><a href="./UniDeskGlobals">UniDeskGlobals</a></td><td>全局主题状态、国际化、应用退出信号</td><td><code>UniDeskGlobals</code></td></tr><tr><td><a href="./UniDeskSettings">UniDeskSettings</a></td><td>用户设置持久化</td><td><code>UniDeskSettings</code></td></tr><tr><td><a href="./UniDeskPluginMgr">UniDeskPluginMgr</a></td><td>插件加载、卸载、元数据管理</td><td><code>UniDeskPluginMgr</code></td></tr><tr><td><a href="./UniDeskTempleteMgr">UniDeskTempleteMgr</a></td><td>模板保存与加载</td><td><code>UniDeskTempleteMgr</code></td></tr><tr><td><a href="./UniDeskExpr">UniDeskExpr</a></td><td><code>%{}</code> 表达式引擎</td><td><code>UniDeskExpr</code></td></tr><tr><td><a href="./UniDeskSystemInfo">UniDeskSystemInfo</a></td><td>CPU、内存、网络、电池数据采集</td><td><code>UniDeskSystemInfo</code></td></tr><tr><td><a href="./UniDeskComponentsData">UniDeskComponentsData</a></td><td>组件与页面 JSON 数据持久化</td><td><code>UniDeskComponentsData</code></td></tr><tr><td><a href="./UniDeskPluginInterface">UniDeskPluginInterface</a></td><td>插件开发抽象接口</td><td>（C++ 接口）</td></tr></tbody></table><h2 id="注册方式" tabindex="-1">注册方式 <a class="header-anchor" href="#注册方式" aria-label="Permalink to &quot;注册方式&quot;">​</a></h2><p>每个 C++ 后端类都有两种注册方式：</p><ol><li><strong>作为 QML 单例</strong>：在 <code>main.cpp</code> 中通过 <code>qmlRegisterSingletonType</code> 注册，QML 中以 <code>UniDeskPluginMgr.method()</code> 形式调用</li><li><strong>作为 QML 类型</strong>：通过 <code>qmlRegisterType</code> 注册，QML 中可以实例化</li></ol><p>大部分后端类以单例方式注册，因为整个应用中只需一份实例。</p><h2 id="线程模型" tabindex="-1">线程模型 <a class="header-anchor" href="#线程模型" aria-label="Permalink to &quot;线程模型&quot;">​</a></h2><ul><li><code>UniDeskGlobals</code>、<code>UniDeskSettings</code>、<code>UniDeskComponentsData</code> 运行在主线程</li><li><code>UniDeskPluginMgr</code> 在插件加载时会创建子线程</li><li><code>UniDeskExpr</code> 通过内部定时器（1000ms）刷新系统数据</li><li><code>UniDeskSystemInfo</code> 的数据采集通过独立线程运行</li></ul><h2 id="相关目录结构" tabindex="-1">相关目录结构 <a class="header-anchor" href="#相关目录结构" aria-label="Permalink to &quot;相关目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UniDesk/CppExt/</span></span>
<span class="line"><span>├── UniDeskGlobals.h / .cpp</span></span>
<span class="line"><span>├── UniDeskSettings.h / .cpp</span></span>
<span class="line"><span>├── UniDeskPluginMgr.h / .cpp</span></span>
<span class="line"><span>├── UniDeskTempleteMgr.h / .cpp</span></span>
<span class="line"><span>├── UniDeskExpr.h / .cpp</span></span>
<span class="line"><span>├── UniDeskSystemInfo.h / .cpp</span></span>
<span class="line"><span>├── UniDeskComponentsData.h / .cpp</span></span>
<span class="line"><span>└── UniDeskPluginInterface.h</span></span></code></pre></div><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../singletons/UniDeskComManager">UniDeskComManager</a> — 调用多个后端单例的高层管理器</li><li><a href="./../overview">控件库概览</a> — 整体控件体系介绍</li><li><a href="./../../custom-developing/plugin">自定义开发</a> — 插件开发指南</li></ul>`,14)]))}const D=t(i,[["render",o]]);export{k as __pageData,D as default};
